df_base = load_data()

COLOR_MAP = {
    "PBA CENTRO-SUR":"#2E75B6","COSTA ATLANTICA":"#1D9E75","COSTA ATLÁNTICA":"#1D9E75",
    "LITORAL":"#3B6D11","MISIONES":"#BA7517","NEA":"#D85A30","GBA":"#534AB7","BS. AS.":"#993556",
    "COMAHUE":"#1A7BAF","PATAGONIA":"#0D4C73","NOA":"#C84B11","CENTRO":"#5C8A1E","CUYO":"#8B1A8B",
}

st.markdown("# 🔮 AURA Energy - Prospeccion eolica futura")
st.markdown("Simula la **ampliacion de los corredores de exportacion** y descubri que nodos ventosos se liberarian. El proyecto con mas viento es el mejor (la energia crece con v³).")
st.markdown("---")

with st.sidebar:
    st.markdown("## 🔮 Escenario futuro")
    st.markdown("**Editá el límite 6 de cada corredor**")
    st.caption("Valor actual real de Cammesa 2T2026 (eolica = base + #2). Cambiá el futuro para simular ampliaciones.")
    st.markdown("---")
    l6_futuro = {}
    for grupo, actual in GRUPOS_L6_ACTUAL.items():
        st.markdown(f"**{grupo}**")
        st.caption(f"Actual: {actual} MW")
        l6_futuro[grupo] = st.number_input(f"Futuro {grupo}", min_value=0, max_value=3000,
            value=int(actual), step=10, key=f"l6_{grupo}", label_visibility="collapsed")
        st.markdown("")
    st.markdown("---")
    st.markdown("### Pesos del ranking")
    st.caption("En prospeccion prioriza el viento (v³).")
    w_v = st.slider("Peso viento (v³)", 0, 100, 90, 5)
    w_mw = 100 - w_v
    st.markdown("---")
    solo_despiertan = st.toggle("Ver solo nodos que despiertan", value=False)
    solo_real = st.toggle("Solo viento medido (Wind Atlas)", value=False)

def recalcular(row):
    g = row["grupo"]
    if g in l6_futuro:
        return min(row["min_sin_l6"], l6_futuro[g])
    return row["min_sin_l6"]

df = df_base.copy()
df["cap_futuro"] = df.apply(recalcular, axis=1)
df["delta"] = df["cap_futuro"] - df["cap_actual"]
df = df[df["cap_futuro"] > 0].copy()
if solo_real:
    df = df[df["v_fuente"]=="real"].copy()

if not df.empty:
    df["v3"] = df["viento"]**3
    vn = (df.v3-df.v3.min())/(df.v3.max()-df.v3.min()) if df.v3.max()!=df.v3.min() else 1.0
    mn = (df.cap_futuro-df.cap_futuro.min())/(df.cap_futuro.max()-df.cap_futuro.min()) if df.cap_futuro.max()!=df.cap_futuro.min() else 1.0
    df["score"] = (w_v/100)*vn + (w_mw/100)*mn
    df["rk"] = df["score"].rank(ascending=False, method="min").astype(int)

df_f = df[df["delta"]>0].copy() if solo_despiertan else df.copy()

total_actual = int(df_base["cap_actual"].sum())
total_futuro = int(df["cap_futuro"].sum())
mw_lib = total_futuro - total_actual
n_desp = (df["delta"]>0).sum()
m1,m2,m3,m4 = st.columns(4)
with m1: st.markdown(f'<div class="metric-card"><div class="metric-lbl">MW actuales</div><div class="metric-val">{total_actual:,}</div></div>', unsafe_allow_html=True)
with m2: st.markdown(f'<div class="metric-card"><div class="metric-lbl">MW futuro</div><div class="metric-val">{total_futuro:,}</div></div>', unsafe_allow_html=True)
with m3: st.markdown(f'<div class="metric-card"><div class="metric-lbl" style="color:#14A085">MW que se liberan</div><div class="metric-val" style="color:#14A085">+{mw_lib:,}</div></div>', unsafe_allow_html=True)
with m4: st.markdown(f'<div class="metric-card"><div class="metric-lbl">Nodos que despiertan</div><div class="metric-val">{n_desp}</div></div>', unsafe_allow_html=True)
st.markdown("---")

tab1,tab2,tab3 = st.tabs(["🏆 Nodos que se liberan", "🗺️ Mapa", "📋 Tabla completa"])

with tab1:
    st.markdown("### Nodos ordenados por potencial eolico (v³)")
    st.caption("El delta muestra cuantos MW gana cada nodo con la ampliacion simulada.")
    ds = df_f.sort_values("rk").head(40)
    if ds.empty: st.info("Ajusta los L6 en el panel izquierdo.")
    for _,r in ds.iterrows():
        cc = COLOR_MAP.get(r.corredor,"#888")
        fb = "📡" if r.v_fuente=="real" else "📍"
        db = f'<span style="background:#D0F0E8;color:#0F6E56;padding:1px 8px;border-radius:10px;font-size:.75rem;font-weight:600">+{int(r.delta)} MW</span>' if r.delta>0 else ''
        st.markdown(f'<div style="border-left:3px solid {cc};padding:6px 10px;margin:3px 0;background:#FAFAFA;border-radius:0 6px 6px 0"><span style="font-weight:600;color:#0F6E56">#{int(r["rk"])} {r["nombre"]}</span> <span style="font-size:.78rem;color:#888">{r.corredor}</span> {db}<br><span style="font-size:.82rem">{fb} <b>{r.viento} m/s</b> - actual <b>{int(r.cap_actual)} MW</b> → futuro <b>{int(r.cap_futuro)} MW</b> - score {r.score:.3f}</span></div>', unsafe_allow_html=True)
    st.caption("📡 = viento medido - 📍 = viento estimado por zona")

with tab2:
    dm = df_f.dropna(subset=["lat","lon"]).copy()
    st.markdown(f"### Mapa ({len(dm)} nodos con coordenadas)")
    st.caption("Tamano = capacidad futura - Color = velocidad de viento")
    if dm.empty: st.info("Sin nodos con coordenadas.")
    else:
        fig = px.scatter_mapbox(dm, lat="lat", lon="lon", color="viento", size="cap_futuro", size_max=28,
            color_continuous_scale="Turbo", hover_name="nombre",
            hover_data={"id":True,"viento":True,"cap_actual":True,"cap_futuro":True,"delta":True,"lat":False,"lon":False},
            zoom=3.7, center={"lat":-38,"lon":-64}, mapbox_style="open-street-map", labels={"viento":"m/s"})
        fig.update_layout(height=560, margin={"r":0,"t":0,"l":0,"b":0})
        st.plotly_chart(fig, use_container_width=True)

with tab3:
    st.markdown("### Tabla completa - escenario simulado")
    cols=["rk","nombre","corredor","grupo","viento","v_fuente","cap_actual","cap_futuro","delta","score","id"]
    dd=df_f[cols].sort_values("rk").copy()
    dd.columns=["Rk","Nombre","Corredor","Grupo","Viento","Fuente","Cap. actual","Cap. futura","Delta","Score","ID"]
    st.dataframe(dd, use_container_width=True, height=500, hide_index=True, column_config={
        "Rk": st.column_config.NumberColumn(format="%d"),
        "Viento": st.column_config.NumberColumn(format="%.2f m/s"),
        "Cap. actual": st.column_config.NumberColumn(format="%d MW"),
        "Cap. futura": st.column_config.NumberColumn(format="%d MW"),
        "Delta": st.column_config.NumberColumn(format="+%d MW"),
        "Score": st.column_config.NumberColumn(format="%.3f")})

st.markdown("---")
st.caption("AURA Energy - Prospeccion eolica sobre MATER 2T2026 - Valores futuros = simulaciones de ampliacion, NO capacidad real hoy - Eolica = base + #2 - Viento: Global Wind Atlas 100m")
